mapper.select:
SELECT count(*)
FROM wms_inbound_order
WHERE deleted = 0
  AND created_at >= #{start}
  AND created_at < #{end}

SELECT count(*)
FROM wms_outbound_order
WHERE deleted = 0
  AND created_at >= #{start}
  AND created_at < #{end}

WITH inventory_rows AS ( SELECT i.sku_id, i.on_hand_qty, GREATEST( COALESCE( (SELECT max(m.created_at) FROM wms_stock_movement m WHERE m.location_id = i.location_id AND m.sku_id = i.sku_id AND m.movement_type = 1 AND m.batch_no IS NOT DISTINCT FROM i.batch_no), i.created_at ), i.created_at ) AS last_inbound_at FROM wms_inventory i JOIN wms_sku s ON s.id = i.sku_id JOIN wms_warehouse w ON w.id = i.warehouse_id WHERE i.deleted = 0 AND i.on_hand_qty > 0
AND i.warehouse_id = #{warehouseId}
AND s.category = #{category}
), aged AS ( SELECT sku_id, on_hand_qty, (CURRENT_DATE - (last_inbound_at AT TIME ZONE 'Asia/Shanghai')::date) AS age_days FROM inventory_rows ) SELECT CASE WHEN age_days <= 30 THEN '0-30天' WHEN age_days <= 60 THEN '31-60天' WHEN age_days <= 90 THEN '61-90天' ELSE '90天以上' END AS groupKey, count(DISTINCT sku_id) AS skuCount, COALESCE(sum(on_hand_qty), 0) AS onHandQty, 0::numeric AS lockedQty, 0::numeric AS availableQty FROM aged GROUP BY 1
